/**
 * Settings match the decision rows word for word (src/lib/decisions.ts appends hand-written questions to the section
 * whose setting matches), plus "Newly diagnosed", the five appointment types and carers.
 */
export const lungQuestions: Question[] = [
  // Newly diagnosed
  { setting: "Newly diagnosed", question: "Who is my lung cancer clinical nurse specialist, and what number do I ring between appointments?", why: "NICE NG122 (1.1.1) says a lung cancer clinical nurse specialist should be available at all stages of care to support people and, as appropriate, their family members or carers, and (1.19.3) that people should know how to contact them between scheduled hospital visits. Every urgent card on this page starts with that number." },
  { setting: "Newly diagnosed", question: "Which type of lung cancer is it, non-small-cell or small-cell, and what stage?", why: "The NHS says the treatment you have depends on the size of the cancer and where it is, the type of lung cancer you have, whether it has spread and whether it has certain genetic changes; the two types run on different timetables, so the answer changes what happens next week." },
  { setting: "Newly diagnosed", question: "Is the aim of treatment to cure the cancer, or to control it and keep me well?", why: "The NHS says that if advanced lung cancer cannot be cured, the aim of treatment will be to slow down the growth and spread of the cancer, to help with symptoms and to help you live longer. Hearing the aim out loud early saves a great deal of confusion later." },
  { setting: "Newly diagnosed", question: "Have the tests on the tumour been sent, and when will the results be back?", why: "NICE NG122 (1.2.11) says samples should be adequate to permit pathological diagnosis including tumour subtyping and assessment of molecular markers, and (1.2.12) points to the National Genomics Test Directory for the sequencing panels that guide treatment; the results decide which treatments are open to you." },
  { setting: "Newly diagnosed", question: "Have I had a PET-CT scan, and do I need a scan of my brain?", why: "NICE NG122 (1.2.4) says all people with lung cancer who could potentially have treatment with curative intent should be offered PET-CT before treatment; brain imaging is a separate question NICE has an open research recommendation on, so it is fair to ask what your team does and why." },
  { setting: "Newly diagnosed", question: "I smoke, or I used to. Does that change my treatment, and what help is there if I want to stop now?", why: "NICE NG122 (1.3.1 to 1.3.3) says to inform people that smoking increases the risk of pulmonary complications after lung cancer surgery, to advise people to stop smoking as soon as the diagnosis is suspected and tell them why this is important, and not to postpone surgery for lung cancer to allow people to stop smoking. Stopping is offered as a treatment with a benefit, not a judgement, and your treatment does not depend on it." },
  { setting: "Newly diagnosed", question: "I have never smoked. Does that change anything about my tests or treatment?", why: "Lung cancer also happens to people who never smoked, and the record notes that some of the targetable changes, ROS1 among them, are enriched in people who never smoked (Bergethon 2012). NICE NG122 (1.2.12) points teams at the National Genomics Test Directory panels whatever your history, so the question to ask is which panel was sent rather than which box you fit." },
  { setting: "Newly diagnosed", question: "When does my case go to the lung multidisciplinary team meeting, and how will I hear what was agreed?", why: "NICE NG122 (1.6.1) says everyone potentially suitable for multimodality treatment should be assessed by a thoracic oncologist and by a thoracic surgeon, which means the plan is made by a group, and you are entitled to know what they concluded and why." },
  { setting: "Newly diagnosed", question: "What can I do in the next few weeks to be in better shape for treatment?", why: "Roy Castle Lung Cancer Foundation's living with lung cancer material covers managing symptoms, keeping active and looking after your physical and mental wellbeing; Cancer Research UK says staying as active as possible matters when you are breathless, and NICE asks for breathing and coping support to be available in all care settings." },

  // Early disease
  { setting: S_EARLY, question: "Am I being offered an operation, radiotherapy, or a choice between them, and why?", why: "NICE NG122 (1.5.1) says that for people who are well enough and for whom treatment with curative intent is suitable, offer lobectomy; (1.5.5) for stage 1 to 2a disease in people who decline lobectomy or in whom it is contraindicated, offer stereotactic ablative radiotherapy or sublobar resection; and (1.5.8) if they decline any surgery or it is contraindicated, offer stereotactic ablative radiotherapy." },
  { setting: S_EARLY, question: "What did my breathing tests show, and what would my breathing be like after the operation?", why: "NICE NG122 (1.4.9) says to perform spirometry and transfer factor testing before treatment with curative intent, and (1.4.11) to perform a functional segment count before surgery to predict postoperative lung function; those two numbers are the heart of this decision, so ask for them in plain terms." },
  { setting: S_EARLY, question: "If my predicted lung function after surgery is low, is an operation still possible?", why: "NICE NG122 (1.4.12) says to offer people with predicted postoperative FEV1 or transfer factor below 30 percent the option of treatment with curative intent if they accept the risks of breathlessness and associated complications; the guideline treats it as your judgement to make with the numbers in front of you, not an automatic refusal." },
  { setting: S_EARLY, question: "How much of my lung would come out, and would it be keyhole or open?", why: "NICE NG122 (1.5.1) names lobectomy, either open or thoracoscopic, and (1.5.2) says to offer more extensive surgery such as bilobectomy or pneumonectomy only when needed to obtain clear margins, so the size of the operation should have a reason you can hear." },
  { setting: S_EARLY, question: "What is my personal risk from this operation?", why: "NICE NG122 (1.4.1) says that when evaluating surgery, consider a global risk score such as Thoracoscore to estimate the risk of death, and ensure the person is aware of the risk before they give consent for surgery. You are entitled to that number before you sign." },
  { setting: S_EARLY, question: "If I have stereotactic radiotherapy instead, how many visits is it and what are the risks?", why: "NICE NG122 notes that stereotactic ablative radiotherapy is non-invasive, is usually delivered as outpatient treatment and that people often prefer it because it involves fewer hospital visits; Cancer Research UK explains that radiotherapy to the chest can inflame the lungs, causing a dry cough or shortness of breath soon after treatment." },
  { setting: S_EARLY, question: "Would stopping smoking now change my operation, and can I be referred today?", why: "NICE NG122 (1.3.1 and 1.3.3) says smoking increases the risk of pulmonary complications after lung cancer surgery and that surgery should not be postponed to allow people to stop; Roy Castle says it is equally important to quit after a diagnosis because research suggests this can help you respond better to treatment. Help is practical (patches, medicines, a local service), and the offer stands whether or not you take it." },

  // Around surgery
  { setting: S_AROUND_SURGERY, question: "Is there a treatment before the operation, and would it delay surgery?", why: "NICE NG122 (1.6.8) says nivolumab with chemotherapy is recommended for neoadjuvant treatment of resectable non-small-cell lung cancer of at least 4 cm or node positive, and (1.6.9 and 1.6.10) that durvalumab or pembrolizumab with platinum chemotherapy are recommended before and then after surgery in defined groups; the trade-off between a few weeks of treatment first and going straight to theatre is a fair thing to ask about." },
  { setting: S_AROUND_SURGERY, question: "Do my EGFR and ALK results need to be back before we decide about treatment before surgery?", why: "NICE NG122 (1.6.9) restricts the durvalumab recommendation to resectable disease without EGFR mutations or ALK rearrangements, and (1.6.14 and 1.6.15) recommends osimertinib after complete resection for EGFR exon 19 deletion or L858R disease and alectinib after complete resection of ALK-positive disease; the result decides between whole treatment routes." },
  { setting: S_AROUND_SURGERY, question: "Will I need chemotherapy after the operation, and what does the pathology report have to say for that?", why: "NICE NG122 (1.6.11) says to offer postoperative systemic anticancer therapy to people with good performance status and T1a to 4, N1 to 2, M0 disease, (1.6.12) to consider it for T2b to 4, N0, M0 tumours greater than 4 cm, and (1.6.13) to offer a platinum-based combination regimen." },
  { setting: S_AROUND_SURGERY, question: "How long would tablet treatment after surgery go on for?", why: "NICE NG122 (1.6.14) says adjuvant osimertinib should be stopped at 3 years, or earlier if there is disease recurrence or unacceptable toxicity; knowing the end date at the start changes how a long course feels." },
  { setting: S_AROUND_SURGERY, question: "If I am having chemoradiotherapy and then surgery, when would the operation be?", why: "NICE NG122 (1.6.5) says that for people with stage 3a N2 disease having chemoradiotherapy and surgery, their surgery should be scheduled for 3 to 5 weeks after completion of the chemoradiotherapy, and explains that the wait is to give people time to recover." },
  { setting: S_AROUND_SURGERY, question: "What should I expect in the first weeks at home after a lung operation?", why: "Cancer Research UK says some breathlessness is normal after lung surgery, that this depends on the type of operation and on how fit you were beforehand, that some people improve as they recover while others have longer term problems, and that you can ask to be referred to a breathlessness clinic." },

  // Locally advanced
  { setting: S_STAGE3, question: "Why chemotherapy and radiotherapy together rather than one after the other?", why: "NICE NG122 (1.6.17) says to consider chemoradiotherapy for people with stage 2 or 3 disease whose condition is not suitable for surgery or who decline it, and to balance the potential benefit in survival against the risk of additional toxicities; the balance is the conversation." },
  { setting: S_STAGE3, question: "Would I have immunotherapy afterwards, and what decides that?", why: "NICE NG122 (1.6.18) says durvalumab is recommended for treating locally advanced unresectable disease with PD-L1 expression on 1 percent or more of tumour cells if disease has not progressed after concurrent platinum-based chemoradiation, so the PD-L1 result and the scan after chemoradiotherapy together decide it." },
  { setting: S_STAGE3, question: "If my tumour has an EGFR change, is there a different treatment after chemoradiotherapy?", why: "The corpus records the LAURA trial of osimertinib after chemoradiotherapy in unresectable stage 3 EGFR-mutant disease; ask your team what is funded for you now and whether a trial applies, because this is an area where practice has moved recently." },
  { setting: S_STAGE3, question: "What are the warning signs of lung inflammation after this treatment, and who do I ring?", why: "Macmillan says durvalumab and pembrolizumab can cause inflammation of the lungs (pneumonitis) and to contact the hospital straight away on the 24-hour number for breathlessness, a cough that does not go away, wheezing, or a fever with a temperature over 37.5 C; Cancer Research UK says radiotherapy to the chest can also inflame the lungs soon after treatment." },
  { setting: S_STAGE3, question: "If I cannot manage chemoradiotherapy, what else is there?", why: "NICE NG122 (1.5.9 and 1.5.10) says to consider radical radiotherapy, conventional or hyperfractionated, for people with stage 3a or 3b disease who are eligible and who cannot tolerate or decline chemoradiotherapy, while noting that some people who cannot tolerate chemoradiotherapy may not manage radical radiotherapy either." },

  // Biomarkers
  { setting: S_BIOMARKERS, question: "Which genes were tested, and can I have the report?", why: "NICE NG122 (1.2.12) points teams to the National Genomics Test Directory for the sequencing panels used to guide treatment; the NHS explains how genomic testing on a tumour sample works and who sees the result. Asking which panel was sent is how you find out whether a gap is a negative result or an untested gene." },
  { setting: S_BIOMARKERS, question: "How long will the results take, and should we wait for them before starting treatment?", why: "For most people with newly diagnosed advanced non-squamous disease the molecular result changes the first treatment completely, so a short wait usually buys a better first choice; ask your oncologist how long yours will be, what would make them start sooner, and what they would start with." },
  { setting: S_BIOMARKERS, question: "Was enough tissue taken, and would a blood test speed things up?", why: "NICE NG122 (1.2.11) asks teams to ensure samples are adequate, without unacceptable risk to the person, to permit subtyping and assessment of molecular markers; where tissue is short, a blood test for tumour DNA can sometimes give an answer sooner, so it is worth asking whether one has been sent." },
  { setting: S_BIOMARKERS, question: "If a targetable change is found, what would the treatment be, and is it tablets or a drip?", why: "The record carries the targeted options by gene (EGFR, ALK, ROS1, KRAS G12C, BRAF, MET, RET, HER2 and NTRK); the practical difference between daily tablets at home and a regular hospital drip matters to how you plan your life, so ask early." },
  { setting: S_BIOMARKERS, question: "If nothing targetable is found, does that mean worse options?", why: "No: it means the route is immunotherapy, with or without chemotherapy, chosen by the PD-L1 score. NICE NG122 sets out separate treatment pathways for squamous and non-squamous disease with no targetable mutations at PD-L1 below and at or above 50 percent." },

  // Immunotherapy
  { setting: S_IMMUNOTHERAPY, question: "What is my PD-L1 score, and what does that number mean for what you are offering?", why: "NICE NG122's treatment pathways for advanced disease are organised around whether PD-L1 is below 50 percent or 50 percent or higher, for squamous and for non-squamous disease separately, so the number is the fork in the road." },
  { setting: S_IMMUNOTHERAPY, question: "Immunotherapy on its own, or with chemotherapy: which are you recommending for me, and why?", why: "A high PD-L1 score opens the option of immunotherapy alone, which is gentler; adding chemotherapy works faster and is often preferred when there is a lot of disease or symptoms are pressing. Ask which consideration is driving the recommendation in your case." },
  { setting: S_IMMUNOTHERAPY, question: "How long would immunotherapy go on for, and what happens when it stops?", why: "Checkpoint treatment is usually given for a fixed period rather than indefinitely, and Macmillan notes that immune side effects can start during treatment or after treatment ends; ask what the plan is at the end and what monitoring continues." },
  { setting: S_IMMUNOTHERAPY, question: "Which symptoms would make me ring you the same day?", why: "Macmillan says to contact the hospital straight away on the 24-hour number for breathlessness, a cough that does not go away, wheezing or a fever over 37.5 C (possible pneumonitis), for passing more stools than is normal for you or passing stools at night (possible colitis), and for a spreading rash, blistering or peeling skin with flu-like symptoms." },
  { setting: S_IMMUNOTHERAPY, question: "Do I get an alert card, and should I carry it?", why: "Macmillan says your team gives you a patient alert card for immunotherapy and 24-hour contact numbers for the hospital, and that you can call at any time of the day or night; the card is how an out-of-hours doctor knows to think of an immune reaction." },

  // Resistance
  { setting: S_RESISTANCE, question: "How will we know the tablet has stopped working, and does one growing spot mean changing everything?", why: "Cancer that grows in one place while the rest stays controlled is sometimes treated locally, with radiotherapy to that spot, while the tablet continues; growth in several places usually means a change of treatment. Ask which pattern yours is." },
  { setting: S_RESISTANCE, question: "Should I have another biopsy to find out why it stopped working?", why: "NICE NG122 (1.2.11) asks that samples be adequate to permit subtyping and assessment of molecular markers, and (1.2.13) that teams choose investigations giving the most information with the least risk to the person; a repeat sample can show a new resistance change or a change of cancer type, which in turn opens or closes options." },
  { setting: S_RESISTANCE, question: "Can this be done as a blood test instead, and what would each test miss?", why: "A blood test for tumour DNA is easier and quicker but cannot show a change in the cancer's appearance under the microscope; a tissue sample can, at the cost of a procedure. Ask which question your team is trying to answer, because that decides which test is the right one." },
  { setting: S_RESISTANCE, question: "What are the options after this drug, and in what order would you use them?", why: "The record carries the later-line options for lung cancer, including chemotherapy, antibody drug conjugates such as patritumab deruxtecan in the HERTHENA-Lung02 setting, and trials; knowing the order in advance makes each step less sudden." },
  { setting: S_RESISTANCE, question: "Is a trial open to me at this point, and should I be referred before I am less well?", why: "The NHS says you can ask your doctor or a patient organisation about clinical trials you may be eligible to join; trials usually need you to be well enough to take part, so the referral is easier earlier than later." },

  // Brain
  { setting: S_BRAIN, question: "What symptoms would mean the cancer has reached my brain, and who do I ring?", why: "Cancer Research UK says cancer that has spread to the brain might cause memory problems, mood or personality changes, seizures, confusion, severe headaches often with sickness, or weakness of an arm or leg; these go to the team rather than being waited out." },
  { setting: S_BRAIN, question: "Am I being offered steroids, and for how long?", why: "NICE NG122 (1.16.1) says to offer dexamethasone to people with symptomatic brain metastases and to reduce to the minimum necessary maintenance dose for symptomatic response; steroids help quickly but have their own effects, so the plan to reduce them matters as much as the plan to start." },
  { setting: S_BRAIN, question: "Focused radiotherapy to the spots, or radiotherapy to the whole brain: which and why?", why: "NICE NG122 (1.16.2) points to the management of confirmed brain metastases in its brain tumours guideline rather than repeating it; NICE says of preventive whole-brain radiotherapy in small-cell disease that it can adversely affect quality of life, so asking what each option costs as well as what it buys is fair." },
  { setting: S_BRAIN, question: "Does my targeted drug reach the brain, and could that be the treatment?", why: "Several of the modern targeted drugs recorded here were designed to cross into the brain, which can sometimes mean treating brain disease with tablets rather than radiotherapy; ask your oncologist whether that applies to your gene change." },
  { setting: S_BRAIN, question: "Can I still drive?", why: "Driving after a seizure or a brain metastasis is governed by DVLA rules rather than by your team, so this is a question to put to them directly rather than a thing to assume either way; Cancer Research UK lists seizures and weakness of an arm or leg among the symptoms of cancer that has spread to the brain." },

  // Trial or standard
  { setting: S_TRIAL, question: "Is there a trial open to me now, here or at another hospital, and what would it involve?", why: "The NHS says you can ask your doctor or a patient organisation if they know of any clinical trials that you may be eligible to join, and that Cancer Research UK's find a clinical trial service lists UK studies." },
  { setting: S_TRIAL, question: "If I join, can I leave, and would standard treatment still be available?", why: "The NHS says you may decide to stop taking part if your condition is getting worse or you feel the treatment is not helping, and that you can also choose to leave at any point without giving a reason and without it affecting the care you receive." },
  { setting: S_TRIAL, question: "How many extra visits, scans or biopsies would the trial need, and are travel costs covered?", why: "The NHS says trials can be time consuming, that you may be expected to attend a number of screening and follow-up sessions and some require an overnight stay, that some trials cover travel expenses, and that it is important to find out about the inconvenience and risks before signing up." },
  { setting: S_TRIAL, question: "Would I definitely get the new treatment?", why: "The NHS explains that in most trials you are randomly assigned either to the treatment being assessed or to a control group given an existing standard treatment, or a placebo where no proven standard treatment exists; knowing that before you consent avoids a painful surprise." },

  // Palliative care
  { setting: S_PALLIATIVE, question: "Can I be referred to the palliative care team now, alongside my treatment?", why: "In lung cancer this is not a symbolic question: a randomised trial in newly diagnosed metastatic non-small-cell lung cancer (Temel 2010) found that people given early palliative care alongside standard oncology care had better quality of life, fewer depressive symptoms (16 against 38 percent), less aggressive care at the end of life and longer median survival (11.6 against 8.9 months)." },
  { setting: S_PALLIATIVE, question: "What can the palliative care team help with that my cancer team cannot?", why: "Marie Curie says palliative care offers physical, emotional and practical support, that it can be offered at any point after a diagnosis, and that you can have it alongside treatments aimed at controlling the illness such as chemotherapy or radiotherapy." },
  { setting: S_PALLIATIVE, question: "Who do I ring out of hours when breathlessness or pain gets out of control at home?", why: "Macmillan says to ask your cancer doctor or specialist nurse who you should contact, how to contact them including at night, on bank holidays and at weekends, and when you should call for help or advice. Write the answer down before you need it." },
  { setting: S_PALLIATIVE, question: "What is available at home, in a hospice and in hospital, and how quickly?", why: "Cancer Research UK describes district and community nurses, community specialist palliative care nurses including Macmillan nurses, and Marie Curie nurses who give nursing care at home during the day or overnight to give carers a break; your GP can usually arrange a specialist nurse visit at home." },
  { setting: S_PALLIATIVE, question: "Can we write down what matters most to me, and who should be asked if I cannot speak?", why: "NICE asks teams to offer opportunities to discuss advance care planning, with support from family and carers if appropriate; writing it down is what makes it usable by an out-of-hours doctor who has never met you." },

  // Appointment types
  { setting: "Respiratory physician appointment", question: "What did the bronchoscopy or biopsy show, and is there enough tissue for all the tests?", why: "NICE NG122 (1.2.8) says to offer endobronchial ultrasound-guided transbronchial needle aspiration for biopsy of paratracheal and peri-bronchial intra-parenchymal lung lesions, and (1.2.11) that samples must be adequate to permit subtyping and assessment of molecular markers; a sample that was too small is a common and fixable reason for a delay." },
  { setting: "Respiratory physician appointment", question: "What are my breathing test numbers, and what do they mean for treatment?", why: "NICE NG122 (1.4.9) says to perform spirometry and transfer factor testing before treatment with curative intent, and (1.4.13 and 1.4.14) describes shuttle walk testing with 400 m as a cut-off for good function and cardiopulmonary exercise testing with more than 15 ml/kg/minute as a cut-off, for people at moderate to high risk of breathlessness after surgery." },
  { setting: "Respiratory physician appointment", question: "Is there fluid around my lung, and would draining it help my breathing?", why: "NICE NG122 (1.15.1) says to perform pleural aspiration or drainage in an attempt to relieve the symptoms of a pleural effusion, and (1.15.2) to offer talc pleurodesis to people who would experience long-term symptomatic benefit from aspiration or drainage." },
  { setting: "Respiratory physician appointment", question: "Can I be referred to a breathlessness service, and is there a physiotherapist who can teach me the techniques?", why: "NICE NG122 (1.15.3 and 1.15.4) says to consider non-pharmacological interventions based on psychosocial support, breathing control and coping strategies, delivered by a multidisciplinary group coordinated by a professional with expertise such as a nurse, physiotherapist or occupational therapist, and that people should have access to this in all care settings." },
  { setting: "Respiratory physician appointment", question: "I have COPD or another lung condition as well. How does that change the plan?", why: "The guideline's fitness assessment is built on lung function and exercise tolerance rather than on the diagnosis label, so the honest answer is a set of numbers; Asthma + Lung UK notes that lung function tests and scans do not always show how breathless you feel, which is worth saying out loud." },

  { setting: "Thoracic surgeon appointment", question: "Draw me what you are taking out and what will be left.", why: "NICE NG122 (1.5.1 and 1.5.2) distinguishes lobectomy from bilobectomy, pneumonectomy and bronchoangioplastic surgery, and says the more extensive operations are only for obtaining clear margins; a drawing turns those words into something you can repeat to your family." },
  { setting: "Thoracic surgeon appointment", question: "What is my Thoracoscore or equivalent risk of dying from this operation?", why: "NICE NG122 (1.4.1) says to consider a global risk score such as Thoracoscore and to ensure the person is aware of the risk before they give consent for surgery." },
  { setting: "Thoracic surgeon appointment", question: "Will you sample the lymph nodes, and how does that change what happens afterwards?", why: "NICE NG122 (1.5.3) says to perform hilar and mediastinal lymph node sampling or en bloc resection for all people having surgery with curative intent; what those nodes show decides whether chemotherapy is offered afterwards." },
  { setting: "Thoracic surgeon appointment", question: "How long in hospital, how long with a chest drain, and how long before I can lift or drive?", why: "Cancer Research UK says some breathlessness is normal after lung surgery and depends on the operation and your fitness beforehand; the practical timeline is what lets you arrange help at home, so ask for it in weeks." },
  { setting: "Thoracic surgeon appointment", question: "How many of these operations does this unit do each year?", why: "NICE NG122 (1.6.7) says centres performing lung resections for lung cancer should validate their data for the National Lung Cancer Audit, so volumes and outcomes are collected nationally; you are allowed to ask about them." },

  { setting: "Oncologist appointment", question: "What is this treatment for: cure, control or symptoms, and over how long?", why: "The NHS says your specialist treatment team will explain the treatments, the benefits and side effects, and work with you to make a plan; the aim of treatment belongs at the top of that conversation." },
  { setting: "Oncologist appointment", question: "Which side effects should make me ring the 24-hour line, and which can wait until the next clinic?", why: "Macmillan's drug pages set the thresholds: a temperature above 37.5 C or below 36 C or feeling unwell with a normal temperature, breathlessness or a new cough, loose stools three or more times a day, unexplained bruising or bleeding, and any spreading or blistering rash." },
  { setting: "Oncologist appointment", question: "How will we know if it is working, and when is the first scan?", why: "Agreeing the scan interval in advance turns a wait into a plan; NICE NG122 (1.19.1) says to offer an initial follow-up appointment with a specialist within 6 weeks of completing treatment and regular appointments after that, rather than relying on the person requesting them when they have symptoms." },
  { setting: "Oncologist appointment", question: "What would make you stop this treatment, and what would come next?", why: "Knowing the stopping rule protects the time you have; NICE NG122 (1.12.2) shows the same principle for small-cell disease, where it asks teams to inform people whose disease has not responded to first-line treatment that there is very limited evidence that second-line chemotherapy will be of benefit." },
  { setting: "Oncologist appointment", question: "What is my follow-up after treatment, and who runs it?", why: "NICE NG122 (1.19.2) says to offer protocol-driven follow-up led by a lung cancer clinical nurse specialist as an option for people with a life expectancy of more than 3 months." },

  { setting: "Genomics appointment", question: "Is this a test on the tumour or a blood test for something inherited?", why: "The NHS explains the difference between genetic and genomic testing and what each can show; most lung cancer testing is on the tumour and says nothing about your children, which is worth hearing plainly." },
  { setting: "Genomics appointment", question: "Which panel was sent, and does it cover all the genes with a treatment attached?", why: "NICE NG122 (1.2.12) refers teams to the National Genomics Test Directory for the sequencing panels used to guide treatment; the directory changes, so the honest question is which version was used for your sample." },
  { setting: "Genomics appointment", question: "What are the possible results, including one that is uncertain, and what would each mean?", why: "A variant of uncertain significance is a common outcome and changes nothing on its own; asking in advance prevents a frightening letter later." },
  { setting: "Genomics appointment", question: "If the sample was not good enough, what happens next?", why: "NICE NG122 (1.2.11) asks teams to take samples adequate for molecular markers without unacceptable risk to the person; an inadequate sample means either a repeat procedure or a blood test, and both take time you should know about." },

  { setting: "Palliative care appointment", question: "What can you help with while I am still having cancer treatment?", why: "Marie Curie says palliative care can be given alongside treatments, therapies and medicines aimed at controlling your illness, and covers symptoms, emotional, spiritual and practical support for you and for the people close to you." },
  { setting: "Palliative care appointment", question: "Can you help with my breathlessness specifically?", why: "NICE NG122 (1.15.3) says to consider non-pharmacological interventions based on psychosocial support, breathing control and coping strategies for people with breathlessness, and (1.15.5) to consider opioids such as codeine or morphine to reduce cough." },
  { setting: "Palliative care appointment", question: "What help is there at home, and how fast can it start?", why: "Cancer Research UK describes district nurses, community specialist palliative care nurses and Marie Curie nurses who visit at home during the day or overnight, and says availability varies by area, so ask what exists where you live." },
  { setting: "Palliative care appointment", question: "What support is there for my family, and for children at home?", why: "Marie Curie says palliative care may also support the people close to you, including friends, family and carers, who may be able to speak with professionals offering practical and emotional support; Maggie's centres are open to family and friends as well." },
  { setting: "Palliative care appointment", question: "What help is there with money, benefits and equipment?", why: "Cancer Research UK says practical things such as benefits, sick pay, prescription costs, grants, work issues, Blue Badge applications, help with travel costs and changes to the house can all be supported, and that getting help early stops them becoming a bigger issue later." },

  // Carers
  { setting: "For carers", question: "What should I watch for at home, and which number do I ring first?", why: "Every red card here starts with the hospital's 24-hour number; Macmillan says to ask the cancer doctor or specialist nurse who to contact, how to contact them at night and at weekends, and when to call." },
  { setting: "For carers", question: "Can I come to appointments and write down what is said?", why: "Cancer Research UK says to make a list of questions before the appointment and to take someone with you to support you, remind you what you wanted to ask and help you remember the information given." },
  { setting: "For carers", question: "What do I do when they are frightened and breathless and I cannot fix it?", why: "Cancer Research UK's breathing advice is something a carer can do too: point a handheld fan at their face, help them into a supported forward lean position, and coach long, relaxed breaths out until the breathing settles; Macmillan has a section specifically on looking after someone with breathlessness." },
  { setting: "For carers", question: "Am I entitled to a carer's assessment, and to any benefits?", why: "The NHS says you are a carer if you look after someone regularly because they are ill, that washing, dressing, medicines, travel to appointments, shopping, bills and simply sitting with someone all count, and that you can ask adult social services at your local council for a carer's assessment; it also lists the benefits carers may claim." },
  { setting: "For carers", question: "Who supports me?", why: "Roy Castle runs a telephone line staffed by lung cancer nurses, face to face groups and an online community; Maggie's centres are free, need no appointment and are open to family and friends as well as to patients." },
  { setting: "For carers", question: "How do I talk about smoking without it becoming an argument?", why: "NICE NG122 (1.3.2) frames stopping smoking as advice given with a reason, not a condition of treatment, and (1.3.3) says surgery is not postponed to allow it; naming it as one more thing the team offers, rather than something owed to you, keeps the conversation about the treatment." },
];

export const sclcQuestions: Question[] = [
  { setting: "Newly diagnosed", question: "How quickly will treatment start, and who do I ring in the meantime?", why: "NICE NG122 (1.8.1) says to arrange for people with small-cell lung cancer to have an assessment by a thoracic oncologist within 1 week of deciding to recommend treatment; (1.1.1) says a lung cancer clinical nurse specialist should be available at all stages of care." },
  { setting: "Newly diagnosed", question: "Is this limited stage or extensive stage, and what does that change?", why: "NICE NG122 splits its recommendations at exactly this point: limited stage (1.10) gets chemotherapy with radiotherapy to the chest and often preventive radiotherapy to the brain, extensive stage (1.11) gets chemotherapy with immunotherapy." },
  { setting: "Newly diagnosed", question: "Is there time to get a second opinion or to think about it?", why: "The one-week assessment standard exists because small-cell lung cancer grows fast and responds quickly to treatment; that is a reason to ask your team directly how much time a decision has, rather than assuming either that there is none or that there is plenty." },

  { setting: S_SCLC_SPEED, question: "How many cycles of chemotherapy, and is immunotherapy added?", why: "NICE NG122 (1.10.1) says to offer people with limited-stage disease 4 to 6 cycles of cisplatin-based combination chemotherapy, substituting carboplatin where kidney function, performance status or other illnesses make that better; (1.11.2) says to offer up to a maximum of 6 cycles for extensive-stage disease depending on response and toxicity, and (1.11.3) points to the appraisals of durvalumab and of atezolizumab added to chemotherapy." },
  { setting: S_SCLC_SPEED, question: "Would I have radiotherapy to the chest at the same time as chemotherapy, and once or twice a day?", why: "NICE NG122 (1.10.2) says to offer twice-daily radiotherapy with concurrent chemotherapy to people with limited-stage disease and a performance status of 0 or 1 whose disease can be encompassed in a radical thoracic radiotherapy volume, starting during the first or second cycle, and (1.10.3) to offer once-daily radiotherapy if the person declines or is unable to have twice daily." },
  { setting: S_SCLC_SPEED, question: "Would I have immunotherapy after chemoradiotherapy?", why: "NICE NG122 (1.10.6) says durvalumab is recommended as an option for treating limited-stage small-cell lung cancer that has not progressed after platinum-based chemoradiotherapy in adults." },
  { setting: S_SCLC_SPEED, question: "Would you offer radiotherapy to my brain even though the scan is clear, and what are the downsides?", why: "NICE NG122 (1.10.5) says to offer prophylactic cranial irradiation at a dose of 25 Gy in 10 fractions to people with limited-stage disease and a performance status of 0 to 2 whose disease has not progressed on first-line treatment, and (1.11.5) to consider it in extensive-stage disease that has responded; NICE also says plainly that it can adversely affect quality of life and that the survival benefits are limited, and has an open research question comparing it with regular MRI scans instead." },
  { setting: S_SCLC_SPEED, question: "If the cancer comes back, what then?", why: "NICE NG122 (1.12.1) says to offer people with relapsed disease assessment by a thoracic oncologist, (1.12.2) to inform people whose disease has not responded to first-line treatment that there is very limited evidence that second-line chemotherapy will be of benefit, (1.12.3) to offer an anthracycline-containing or a further platinum-based regimen where chemotherapy is suitable, and (1.12.5) to offer radiotherapy for palliation of local symptoms." },
  { setting: S_SCLC_SPEED, question: "Given how fast this moves, can I see palliative care alongside treatment from the start?", why: "The randomised evidence for early palliative care in lung cancer is from metastatic non-small-cell disease (Temel 2010, better quality of life, fewer depressive symptoms and longer median survival), but the reasoning about symptom control and planning applies at least as strongly when the timeline is short; Marie Curie says palliative care can be given alongside treatments aimed at controlling the illness." },
  { setting: S_SCLC_SPEED, question: "What should I sort out now rather than later?", why: "Roy Castle's living with lung cancer material has a getting organised section on sorting paperwork and putting affairs in order, framed as regaining control rather than giving up; with a fast-moving cancer, doing it early means doing it while you feel well." },

  { setting: "For carers", question: "What changes should make me ring the team rather than wait?", why: "The red cards on this page list breathlessness at rest, signs of sepsis, swelling of the face or neck, coughing up more than a few streaks of blood, new weakness or numbness in the legs with back pain, and confusion; with small-cell disease things change quickly, so ringing early is the right instinct." },
  { setting: "For carers", question: "Am I entitled to a carer's assessment and to carer's benefits?", why: "The NHS says a carer's assessment is for anyone looking after another person regularly because they are ill, is arranged through adult social services at your local council, usually lasts at least an hour, and is separate from the assessment of the person you care for." },
];

// ---------------------------------------------------------------- supplements onto records other files own
/**
 * Supplements (Spike.supplements, applied by applySpikeSupplements): each attaches the lung cancer ids to a symptom,
 * procedure or support record another file owns, with the sourced lung-specific note and the patient pages it was
 * read from. A supplement never creates a record, so a missing id fails the build rather than inventing one.
 */
const BOTH = [LUNG_CANCER_ID, NSCLC_CANCER_ID, SCLC_CANCER_ID];
const NON_SMALL_CELL = [LUNG_CANCER_ID, NSCLC_CANCER_ID];

const supplements: SpikeSupplement[] = [
  { id: "lobectomy", cancers: NON_SMALL_CELL, links: [NG122_MANAGEMENT, MAC_NSCLC, CRUK_BREATHLESSNESS],
    notes: [
      "Lung cancer: NICE NG122 (1.5.1) says that for people with non-small-cell lung cancer who are well enough and for whom treatment with curative intent is suitable, offer lobectomy, either open or thoracoscopic, and (1.5.2) offer more extensive surgery (bronchoangioplastic surgery, bilobectomy, pneumonectomy) only when needed to obtain clear margins. NICE's own rationale calls lobectomy a good compromise between preserving lung function and being more likely to remove cancerous cells than a sublobar resection.",
      "Before the operation NICE asks for spirometry and transfer factor testing (1.4.9), a functional segment count to predict lung function afterwards (1.4.11), and a global risk score such as Thoracoscore with the person made aware of the risk before consent (1.4.1). Cancer Research UK says some breathlessness after lung surgery is normal, depends on the operation and on how fit you were beforehand, improves for some people and persists for others, and that you can ask to be referred to a breathlessness clinic.",
    ] },
  { id: "segmentectomy", cancers: NON_SMALL_CELL, links: [NG122_MANAGEMENT],
    notes: ["Lung cancer: NICE NG122 (1.5.5) says that for people with stage 1 to 2a disease who decline lobectomy or in whom it is contraindicated, offer radical radiotherapy with stereotactic ablative radiotherapy or sublobar resection. NICE's rationale says both give better survival than conventionally fractionated radiotherapy, and that the evidence does not show which of the two is better, which is why the choice is a shared one rather than a rule."] },
  { id: "pneumonectomy", cancers: NON_SMALL_CELL, links: [NG122_MANAGEMENT],
    notes: ["Lung cancer: NICE NG122 (1.5.2) says to offer more extensive surgery, including pneumonectomy, only when needed to obtain clear margins, so removing a whole lung should always have a stated reason. The predicted postoperative lung function recommendation (1.4.12) applies most sharply here: NICE says to offer people with predicted postoperative FEV1 or transfer factor below 30 percent the option of treatment with curative intent if they accept the risks of breathlessness and associated complications."] },
  { id: "sbrt", cancers: BOTH, links: [NG122_MANAGEMENT, CRUK_BREATHLESSNESS],
    notes: ["Lung cancer: NICE NG122 (1.5.8) says that for people with stage 1 to 2a non-small-cell lung cancer who decline surgery or in whom any surgery is contraindicated, offer stereotactic ablative radiotherapy, and if that is contraindicated offer either conventional or hyperfractionated radiotherapy; (1.5.11) says to follow the SABR Consortium guidance on fractionation. NICE's rationale notes that it is non-invasive, usually delivered as outpatient treatment, and often preferred because it involves fewer hospital visits. Cancer Research UK says radiotherapy to the chest can inflame the lungs, causing a dry cough or shortness of breath soon after treatment (acute radiation pneumonitis), and that in a small number of people cough and breathlessness continue months or years later."] },
  { id: "radiation-pneumonitis", cancers: BOTH, links: [CRUK_BREATHLESSNESS, NG122_MANAGEMENT, MAC_DURVA],
    notes: ["Lung cancer: Cancer Research UK says radiotherapy to the chest area might cause some inflammation of the lungs, that soon after treatment you might have a dry cough or shortness of breath (acute radiation pneumonitis), and that in a small number of people a cough and breathlessness continue because of chronic radiation pneumonitis, which might start many months or a few years after treatment. Because immunotherapy given after chemoradiotherapy can cause lung inflammation too, the same symptoms are reported the same way: Macmillan says to contact the hospital straight away on the 24-hour number for breathlessness, a cough that does not go away, wheezing, or a fever with a temperature over 37.5 C."] },
  { id: "irae", cancers: BOTH, links: [MAC_PEMBRO, MAC_DURVA, MAC_ATEZO],
    notes: ["Lung cancer: checkpoint treatment is used at every stage of lung cancer, so the same warning list applies whether it is given before surgery, after chemoradiotherapy or for cancer that has spread. Macmillan says to contact the hospital straight away on the 24-hour number for breathlessness, a cough that does not go away, wheezing or a fever over 37.5 C (lung inflammation); for passing more stools than is normal for you or passing stools at night (bowel inflammation); for a spreading rash, blistering or peeling skin with flu-like symptoms; and for a temperature above 37.5 C or below 36 C or feeling unwell with a normal temperature. It also says these can start during treatment or after treatment ends, which is why the patient alert card is worth carrying."] },
  { id: "immune-colitis", cancers: BOTH, links: [MAC_PEMBRO],
    notes: ["Lung cancer: Macmillan says to contact the hospital straight away on the 24-hour number during or after checkpoint treatment for passing more stools than is normal for you, passing stools at night, or a stoma that is more active than usual, and separately that if you have not been able to pass stools for over 2 days and are being sick, to contact the 24-hour number straight away."] },
  { id: "pleural-effusion", cancers: BOTH, links: [CRUK_PLEURAL, NG122_PALLIATIVE, MAC_BREATHLESSNESS],
    notes: [
      "Lung cancer: Cancer Research UK says fluid can build up between the two sheets of tissue covering the lungs when cancer inflames them or blocks the drainage, that the extra fluid stops the lungs expanding fully so you take shallower breaths and work harder to breathe, that breathlessness may be the first and only symptom although cough and chest pain also occur, and that if you suddenly become breathless or your breathing gets worse you should call 999 or go to A&E straight away.",
      "NICE NG122 (1.15.1) says to perform pleural aspiration or drainage in an attempt to relieve the symptoms of a pleural effusion, and (1.15.2) to offer talc pleurodesis to people who would experience long-term symptomatic benefit from aspiration or drainage.",
    ] },
  { id: "pleurodesis", cancers: BOTH, links: [CRUK_PLEURAL, NG122_PALLIATIVE],
    notes: ["Lung cancer: NICE NG122 (1.15.2) says to offer talc pleurodesis to people who would experience long-term symptomatic benefit from aspiration or drainage of fluid. Cancer Research UK explains what to expect: the fluid drains slowly, because draining a large amount too quickly can drop your blood pressure or make you more breathless as the lung re-expands; a pleurodesis usually means a couple of nights in hospital or longer; and where fluid keeps coming back some people go home with a thin indwelling chest tube with a valve, drained at hospital or sometimes at home with a nurse's help."] },
  { id: "brain-metastases", cancers: BOTH, links: [CRUK_METASTATIC_SYMPTOMS, NG122_PALLIATIVE],
    notes: ["Lung cancer: Cancer Research UK says cancer that has spread to the brain might cause memory problems, mood or personality changes, seizures, confusion, severe headaches often with sickness, or weakness of an arm or leg. NICE NG122 (1.16.1) says to offer dexamethasone to people with symptomatic brain metastases and to reduce to the minimum necessary maintenance dose for symptomatic response, and (1.16.2) points to the management of confirmed brain metastases in its brain tumours guideline for the treatment itself."] },
  { id: "bone-metastases", cancers: BOTH, links: [NG122_PALLIATIVE, NG234],
    notes: ["Lung cancer: NICE NG122 (1.17.1) says to offer single-fraction radiotherapy to people with bone metastasis who need palliation and for whom standard pain relief is inadequate, and points to its guideline on spinal metastases and metastatic spinal cord compression. NG234 lists the pain that should prompt a call within 24 hours (severe unremitting back pain, progressive back pain, pain aggravated by standing, sitting, moving, coughing, sneezing or straining, night-time pain disturbing sleep, localised tenderness) and the symptoms treated as an oncological emergency (bladder or bowel problems, difficulty walking, limb weakness, numbness or altered sensation, radicular pain)."] },
  { id: "cancer-related-fatigue", cancers: BOTH, links: [CRUK_COPING, ROY_CASTLE_LIVING, MAC_BREATHLESSNESS],
    notes: ["Lung cancer: Cancer Research UK says tiredness and feeling lethargic much of the time are common during treatment and for some months afterwards, and also when the cancer has spread, and that resting but also doing some gentle physical activity can help. Breathlessness and anaemia are separate, treatable contributors: Macmillan says low red blood cells make you tired and breathless and may need a blood test and sometimes a transfusion, so tiredness is worth reporting rather than absorbing."] },
  { id: "anaemia", cancers: BOTH, links: [CRUK_BREATHLESSNESS, MAC_BREATHLESSNESS],
    notes: ["Lung cancer: Cancer Research UK lists a low red blood cell count as a cause of breathlessness in lung cancer, explains that haemoglobin carries oxygen so a low level leaves the blood carrying less, and says anaemia can be due to the cancer or to a treatment such as chemotherapy. Macmillan says you may need a blood test to check and that some people need a transfusion. It is worth asking about, because it is one of the causes of breathlessness that can be corrected quickly."] },
  { id: "cachexia", cancers: BOTH, links: [CRUK_BREATHLESSNESS, NG122_PALLIATIVE],
    notes: ["Lung cancer: Cancer Research UK says the muscles that help with breathing can become weaker in some people with lung cancer, often because of cachexia, a complex change in the body causing loss of muscle and often fat, which is one reason breathlessness and weight loss travel together. NICE NG122 (1.18.1) says weight loss, loss of appetite, depression and difficulty swallowing should be managed by multidisciplinary groups that include supportive and palliative care professionals."] },
  { id: "oncology-nutrition", cancers: BOTH, links: [MAC_BREATHLESSNESS, CRUK_BREATHLESSNESS, NG122_PALLIATIVE],
    notes: ["Lung cancer: eating is harder when breathing is hard. Macmillan advises sitting up at a table so breathing feels less restricted, smaller meals on a smaller plate, avoiding chewy food, eating slowly with smaller mouthfuls, adding sauces or gravies, sipping fluid often, and using ready meals on difficult days; it says high-protein powders and high-calorie drinks can be prescribed by a GP or dietitian. Cancer Research UK adds that you lose a lot of fluid through your breath, especially breathing through your mouth, and that dehydration makes saliva and phlegm sticky and harder to swallow."] },
  { id: "pain-management", cancers: BOTH, links: [NG122_PALLIATIVE, CRUK_COPING],
    notes: ["Lung cancer: NICE NG122 (1.17.1) says to offer single-fraction radiotherapy to people with bone metastasis who need palliation and for whom standard pain relief is inadequate, and (1.15.5) to consider opioids such as codeine or morphine to reduce cough. Cancer Research UK says surgery can cause scarring or pain afterwards, that there is a great deal a team can do including changing pain medicines and teaching relaxation techniques, and that pain should be raised rather than tolerated."] },
  { id: "palliative-care", cancers: BOTH, links: [TEMEL_2010, MARIE_CURIE, NG122_PALLIATIVE, NHS_LUNG_TREATMENT],
    notes: [
      "Lung cancer has the randomised evidence for starting palliative care early. Temel and colleagues (NEJM 2010) randomly assigned 151 people with newly diagnosed metastatic non-small-cell lung cancer to early palliative care integrated with standard oncology care or to standard oncology care alone. At 12 weeks the early palliative care group had better quality of life (mean FACT-L 98.0 against 91.5, P equals 0.03) and fewer depressive symptoms (16 against 38 percent, P equals 0.01); fewer received aggressive care at the end of life (33 against 54 percent, P equals 0.05) and median survival was longer (11.6 against 8.9 months, P equals 0.02). It is one of the few places in oncology where the supportive treatment improved survival.",
      "The NHS says that where lung cancer cannot be cured you will be referred to a symptom control or palliative care team who help you manage symptoms, feel more comfortable and get other support for you and your loved ones. Marie Curie says palliative care can be offered at any point after a diagnosis and alongside treatments aimed at controlling the illness such as chemotherapy or radiotherapy, and that it may also support the people close to you.",
    ] },
  { id: "palliative-radiotherapy", cancers: BOTH, links: [NG122_PALLIATIVE],
    notes: ["Lung cancer: NICE NG122 (1.13.1) says to provide palliative radiotherapy, either as symptoms arise or immediately, for people who are eligible and cannot have curative treatment; (1.14.2) to offer external beam radiotherapy and/or endobronchial debulking or stenting to people with impending endobronchial obstruction; (1.15.7) for people who present with superior vena cava obstruction, to offer chemotherapy and radiotherapy based on the stage of disease and performance status; and (1.12.5) to offer radiotherapy for palliation of local symptoms in small-cell lung cancer that has relapsed."] },
  { id: "bronchoscopy", cancers: BOTH, links: [NG122_DIAGNOSIS, NHS_LUNG_TESTS, CRUK_BREATHE_TREATMENTS],
    notes: [
      "Lung cancer: the NHS names CT and bronchoscopy as the two main tests, describing bronchoscopy as a thin flexible tube with a small camera passed down the throat into the lungs. NICE NG122 (1.2.8) says to offer endobronchial ultrasound-guided transbronchial needle aspiration for biopsy of paratracheal and peri-bronchial intra-parenchymal lung lesions, (1.2.9) that every cancer alliance should have at least one centre with endobronchial or endoscopic ultrasound to ensure timely access, and (1.2.11) that samples must be adequate to permit subtyping and assessment of molecular markers.",
      "Bronchoscopy is also a route to treatment when an airway is blocked: NICE NG122 (1.14.1 to 1.14.3) says to monitor for endobronchial obstruction where there is large airway involvement, to offer external beam radiotherapy and/or endobronchial debulking or stenting for impending obstruction, and that every cancer alliance should ensure rapid access to a team capable of providing interventional endobronchial treatments.",
    ] },
  { id: "pet-ct", cancers: NON_SMALL_CELL, links: [NG122_DIAGNOSIS],
    notes: ["Lung cancer: NICE NG122 (1.2.4) says to ensure that all people with lung cancer who could potentially have treatment with curative intent are offered PET-CT before treatment, and (1.2.5) that every cancer alliance should have a system of rapid access to PET-CT scanning for people who are eligible. If an operation or radical radiotherapy is being discussed and no PET-CT has been arranged, that is a fair thing to ask about."] },
  { id: "liquid-biopsy", cancers: NON_SMALL_CELL, links: [NG122_DIAGNOSIS, NHS_GENOMIC],
    notes: ["Lung cancer: a blood test for tumour DNA can sometimes return a targetable result sooner than a repeat tissue sample, or where the sample was too small. NICE NG122 (1.2.11) asks for samples adequate to permit assessment of molecular markers without unacceptable risk to the person, and (1.2.13) to choose investigations that give the most information with the least risk, which is the trade-off a blood test is weighed against. A blood test cannot show a change in how the cancer looks under the microscope, so where that is the question a tissue sample is still needed."] },
  { id: "ngs", cancers: NON_SMALL_CELL, links: [NG122_DIAGNOSIS, NHS_GENOMIC],
    notes: ["Lung cancer: NICE NG122 (1.2.12) says to see the National Genomics Test Directory for guidance on next-generation sequencing panels to guide treatment. In practice this is the single test that decides between tablets, immunotherapy and chemotherapy for most people with advanced non-squamous disease, which is why waiting a short time for the result is usually a better decision than starting quickly on the wrong route. The NHS explains that your hospital specialist requests the test, usually on a sample already taken."] },
  { id: "low-dose-ct-screening", cancers: NON_SMALL_CELL, links: [ROY_CASTLE_DIAGNOSED, NHS_LUNG_SYMPTOMS],
    notes: ["Lung cancer in the UK: Roy Castle Lung Cancer Foundation runs information on lung health checks, the NHS targeted lung cancer screening programme, and supports the roll-out of screening and self-request chest X-ray services. For someone already diagnosed, the relevant part is family and friends: the NHS says to see a GP for a cough lasting longer than 3 weeks or any other symptom of lung cancer, and to ask for an urgent GP appointment or NHS 111 help after coughing up blood."] },
  { id: "psycho-oncology", cancers: BOTH, links: [CRUK_COPING, MAGGIES, ROY_CASTLE_SUPPORT, MAC_BREATHLESSNESS],
    notes: [
      "Lung cancer carries a stigma no other common cancer carries, because of its link with smoking. People who smoked, people who gave up years ago and people who never smoked all report being asked the same question, and all of them report the same effect: it makes asking for help harder. Nothing in this record treats the diagnosis as a consequence. Cancer Research UK lists shock, numbness, fear, confusion, anger, guilt and sadness among the feelings people describe, says everyone reacts in their own way, and says specialist nurses are usually the first point of call if you are finding it difficult to cope.",
      "Practical routes in: Cancer Research UK's nurse freephone line and Cancer Chat forum; Roy Castle's telephone support from lung cancer nurses, face to face information days and support groups, and its podcast and patient stories; Maggie's centres, which are free, need no appointment and are open to family and friends. Macmillan notes that breathlessness and anxiety feed each other, so psychological support is part of the treatment for the symptom rather than an optional extra.",
    ] },
  { id: "peer-support-groups", cancers: BOTH, links: [ROY_CASTLE_SUPPORT, CRUK_LUNG_RESOURCES, MAGGIES],
    notes: ["Lung cancer: Roy Castle Lung Cancer Foundation offers support online, in person and by phone, with information days, support groups and community events, a telephone line staffed by lung cancer nurses, free booklets, patient stories and a podcast. Cancer Research UK keeps a list of lung cancer resources and support organisations, and runs Cancer Chat. Maggie's centres are open without an appointment to patients and to family and friends."] },
  { id: "exercise-during-chemotherapy", cancers: BOTH, links: [ALUK_BREATHLESSNESS, ALUK_MANAGE, CRUK_BREATHLESSNESS],
    notes: ["Lung cancer: Asthma + Lung UK says lung function tests and scans do not always show how breathless you feel, because the way you breathe, your lifestyle and how you think and feel about breathing all affect breathlessness, and that breathing techniques and changing position can be learned. Cancer Research UK says walking and stairs are easier with breathing control, to match your breathing to your steps, to avoid holding your breath when climbing or bending, and to breathe out on effort (blow as you go)."] },
  { id: "cbt-fatigue-distress", cancers: BOTH, links: [CRUK_BREATHLESSNESS, MAC_BREATHLESSNESS, NG122_PALLIATIVE],
    notes: ["Lung cancer: NICE NG122 (1.15.3) says to consider non-pharmacological interventions based on psychosocial support, breathing control and coping strategies for people with breathlessness, and (1.15.4) that they should be delivered by a multidisciplinary group coordinated by a professional with expertise in the techniques, and be available in all care settings rather than only in a breathlessness clinic. Cancer Research UK explains why the psychological part is not optional: anxiety makes breathlessness worse, which makes anxiety worse, and slowing the breathing deliberately is what interrupts it."] },
  { id: "survivorship-care-plan", cancers: BOTH, links: [NG122_FOLLOW_UP, NG122_CNS, CRUK_LUNG_LIVING],
    notes: ["Lung cancer: NICE NG122 (1.19.1) says to offer everyone with lung cancer an initial follow-up appointment with a specialist within 6 weeks of completing treatment to discuss ongoing care, and regular appointments after this rather than relying on the person requesting appointments when they have symptoms; (1.19.2) to offer protocol-driven follow-up led by a lung cancer clinical nurse specialist as an option for people with a life expectancy of more than 3 months; and (1.19.3) to ensure people know how to contact that nurse between scheduled hospital visits."] },
  { id: "multidisciplinary-tumour-board", cancers: BOTH, links: [NG122_MANAGEMENT],
    notes: ["Lung cancer: NICE NG122 (1.6.1) says to ensure that all people whose condition is potentially suitable for multimodality treatment (surgery, radiotherapy and systemic anticancer therapy in any combination) are assessed by a thoracic oncologist and by a thoracic surgeon, and (1.6.6) that teams providing chemoradiotherapy with surgery should have expertise in multimodality treatment and in all of the individual components. Being seen by both a surgeon and an oncologist is the standard, not a second opinion."] },
  { id: "financial-navigation", cancers: BOTH, links: [ROY_CASTLE_LIVING, CRUK_COPING],
    notes: ["Lung cancer in the UK: Cancer Research UK lists money matters, benefits, sick pay, prescription costs and grants, work issues, early retirement, childcare, Blue Badge applications, help with travel costs and changes to the house among the practical things people need help with, says a hospital social worker can help, and says getting help early stops these becoming a bigger issue later. Roy Castle has sections on working with lung cancer and employment rights, financial support, and travel and travel insurance."] },
  { id: "germline-testing", cancers: NON_SMALL_CELL, links: [NHS_GENOMIC, NG122_DIAGNOSIS],
    notes: ["Lung cancer: most genomic testing in lung cancer is done on the tumour and says nothing about what you may have passed on, which is worth saying plainly because the two kinds of test are easily confused. The NHS explains the difference between genetic testing for inherited conditions and genomic testing of a tumour to guide treatment; NICE NG122 (1.2.12) points teams to the National Genomics Test Directory for the tumour panels."] },
  { id: "checkpoint-inhibitor", cancers: BOTH, links: [NG122_MANAGEMENT, MAC_PEMBRO, MAC_DURVA, MAC_ATEZO],
    notes: ["Lung cancer: NICE NG122 places checkpoint treatment at four separate points, which is why the same side-effect list keeps reappearing. Before and after surgery: nivolumab with chemotherapy (1.6.8), durvalumab with platinum chemotherapy (1.6.9) and pembrolizumab with platinum chemotherapy (1.6.10) for resectable disease. After chemoradiotherapy: durvalumab for locally advanced unresectable disease with PD-L1 on 1 percent or more of tumour cells (1.6.18), and for limited-stage small-cell disease that has not progressed (1.10.6). For advanced disease: the treatment pathways organised by PD-L1 below or at or above 50 percent. For extensive-stage small-cell disease: durvalumab or atezolizumab added to chemotherapy (1.11.3)."] },
  { id: "performance-status", cancers: BOTH, links: [NG122_MANAGEMENT],
    notes: ["Lung cancer: NICE NG122 uses performance status as a threshold in several places, so it is worth knowing what yours is recorded as. It asks for twice-daily radiotherapy with chemotherapy in limited-stage small-cell disease for people with a performance status of 0 or 1 (1.10.2), preventive brain radiotherapy for 0 to 2 (1.10.5), postoperative chemotherapy for WHO 0 or 1 (1.6.11 and 1.6.12), and says a clinical oncologist specialising in thoracic oncology should determine suitability for radical radiotherapy taking performance status and other illnesses into account (1.4.15)."] },
];

